INSERT INTO "revisions" VALUES('2fac61ae97cce7137c4838f27c00c3f6894687ad27cdbc6a23e81a44c80add14','legacy_resource_names','{"entry":"main.nex","files":{"main.nex":"module legacy_resource_names;\npub struct file{data:bytes;}\nfn identity<resource:wire>(value:resource)->resource{return unwrap(decode_json<resource>(encode_json(value)));}\nfn file_open_read(value:file)->file{return value;}\nfn file_open_write(value:file)->file{return value;}\nfn file_read(value:file)->file{return value;}\nfn file_write(value:file)->file{return value;}\nfn file_seek(value:file)->file{return value;}\nfn file_close(value:file)->file{return value;}\nfn transform(callback:fn(file)->file,value:file)->file{return callback(value);}\nfn main()->unit!{io}{\n let original:file=file(unwrap(bytes([0,255,128,65])));\n let callback:fn(file)->file=fn(value:file)->file{return file(original.data+value.data);};\n print(identity(transform(callback,file(unwrap(bytes([1]))))));\n let opened:file=file_open_write(file_open_read(original));\n let copied:file=file_seek(file_write(file_read(opened)));\n print(encode_json(file_close(copied)));\n}\ntest fn preserved_names()->unit{\n let value:file=file(utf8_bytes(\"text\"));\n assert(identity(value)==value);\n let opened:file=file_open_write(file_open_read(value));\n let copied:file=file_seek(file_write(file_read(opened)));\n assert(file_close(copied)==value);\n}\n"},"schema":"nex.sources/1"}','/Users/sae/projects/NEX/build/genuine-language-013-capture/0.13-resource-names/main.nex','2026-10-18T05:33:18.980Z','0.13');
